// Custom Worker entry around the OpenNext handler, so the Durable Object class can be exported from the same
// script: opennext.js.org/cloudflare/howtos/custom-worker
// @ts-expect-error -- generated by `opennextjs-cloudflare build`; not present at type-check time.
import { default as handler } from "../.open-next/worker.js";
import { verifyTicket } from "../src/features/realtime/domain/ticket";

import { TICKET_HEADERS } from "./project-room";

export { ProjectRoom } from "./project-room";

const REALTIME_PATH = /^\/realtime\/([^/]+)$/;

interface NextHandler {
  fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response>;
}

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    const match = REALTIME_PATH.exec(url.pathname);
    if (!match?.[1]) return (handler as NextHandler).fetch(request, env, ctx);

    if (request.headers.get("Upgrade") !== "websocket") return new Response("Expected WebSocket", { status: 426 });
    const secret = env.REALTIME_SECRET;
    if (!secret) return new Response("Realtime disabled", { status: 404 });
    const projectId = decodeURIComponent(match[1]);
    const claims = await verifyTicket(url.searchParams.get("ticket") ?? "", secret, projectId, Date.now());
    if (!claims) return new Response("Invalid ticket", { status: 401 });
    // Hand the verified claims to the room, which enforces single use and revocation and tags the socket.
    const headers = new Headers(request.headers);
    headers.set(TICKET_HEADERS.userId, claims.userId);
    headers.set(TICKET_HEADERS.jti, claims.jti);
    headers.set(TICKET_HEADERS.iat, String(claims.iat));
    headers.set(TICKET_HEADERS.exp, String(claims.exp));
    return env.PROJECT_ROOM.getByName(projectId).fetch(new Request(request, { headers }));
  },
} satisfies ExportedHandler<Env>;
